    finalVersion: finalDoc.version,
    finalContent: finalDoc.content
  };

  fs.writeFileSync(
    '/home/user/myproject/optimistic_result.json',
    JSON.stringify(result, null, 2)
  );
  console.log('Wrote optimistic_result.json:', result);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
